<script setup lang="ts">
import 'vue3-lottie/dist/style.css'

import { onMounted } from 'vue'
import { Vue3Lottie } from 'vue3-lottie'

import LottieLoading from '@/public/lottie/lottie.json'

interface Props {
  customLoading?: boolean
}
const props = withDefaults(defineProps<Props>(), {
  customLoading: undefined,
})

const fullSvg = ref(false)
const loading = ref(true)
// const store = useStore()
// const mainLoading = computed(() => store.mainLoading)

onMounted(() => {
  const body = document.body
  body.style.overflow = 'hidden'
  setTimeout(() => {
    fullSvg.value = true
  }, 1000)

  setTimeout(() => {
    fullSvg.value = true
  }, 1000)

  setTimeout(() => {
    body.style.overflow = ''
    loading.value = false
  }, 2000)
})

watch(
  () => props.customLoading,
  (newValue) => {
    if (typeof newValue !== 'undefined') {
      loading.value = newValue
    }
  },
  {
    immediate: true,
  }
)
</script>

<style scoped>
.background-shadow-loader {
  backdrop-filter: blur(28px);
}
@keyframes animateFirstPath {
  0% {
    fill: #52618f;
  }
  100% {
    fill: #a2bcde;
  }
}
@keyframes rotate {
  from {
    transform: rotate(0deg) translate3d(0, 0, 0);
  }
  to {
    transform: rotate(359deg) translate3d(0, 0, 0);
  }
}

@keyframes rotate-reverse {
  from {
    transform: rotate(359deg);
  }
  to {
    transform: rotate(0deg);
  }
}
</style>

<style>
svg.spinner {
  width: 80px;
  height: 80px;
}
svg.spinner circle {
  fill: transparent;
  stroke: #0067ff;
  stroke-width: 6;
  stroke-linecap: round;
  stroke-dasharray: 130;
  transform-origin: 40px 40px 0;
  animation: spinner 3s linear infinite;
}
svg.spinner circle.small {
  position: absolute;
  stroke: #72abff;
  stroke-width: 4.5;
  top: 0;
  left: 0;
  stroke-dasharray: 70;
  animation: spinner 3s linear infinite;
}

@keyframes spinner {
  0% {
    transform: rotate(0deg);
  }
  50% {
